 12	export const ChatBox = {
 13	    setup() {
 14	        const storageKey = 'petclinic.chat.messages';
 15	        const minimized = ref(false);
 16	        const message = ref('');
 17	        const messages = ref([]);
 18	        const messageContainer = ref(null);
 19	
 20	        function save() {
 21	            localStorage.setItem(storageKey, JSON.stringify(messages.value));
 22	        }
 23	
 24	        function scrollToBottom() {
 25	            nextTick(() => {
 26	                if (messageContainer.value) {
 27	                    messageContainer.value.scrollTop = messageContainer.value.scrollHeight;
 28	                }
 29	            });
 30	        }
 31	
 32	        async function send() {
 33	            const query = message.value.trim();
 34	            if (!query) {
 35	                return;
 36	            }
 37	
 38	            messages.value.push({
 39	                author: 'user',
 40	                content: query
 41	            });
 42	            message.value = '';
 43	            scrollToBottom();
 44	
 45	            const errorContext = clearError();
 46	            try {
 47	                const answer = await request('/api/genai/chatclient', jsonRequest('POST', query));
 48	                messages.value.push({
 49	                    author: 'bot',
 50	                    content: answer
 51	                });
 52	            } catch (error) {
 53	                reportError(error, errorContext);
 54	                messages.value.push({
 55	                    author: 'bot',
 56	                    content: 'Chat is currently unavailable'
 57	                });
 58	            }
 59	            scrollToBottom();
 60	        }
 61	
 62	        onMounted(() => {
 63	            try {
 64	                const savedMessages = JSON.parse(localStorage.getItem(storageKey) || '[]');
 65	                if (Array.isArray(savedMessages)) {
 66	                    messages.value = savedMessages.filter((entry) =>
 67	                        entry && (entry.author === 'user' || entry.author === 'bot') && typeof entry.content === 'string');
 68	                }
 69	            } catch {
 70	                // Corrupted saved conversation: discard it and start with an empty chat.
 71	                localStorage.removeItem(storageKey);
 72	            }
 73	            scrollToBottom();
 74	        });
 75	
 76	        watch(messages, save, {
 77	            deep: true
 78	        });
 79	
