  8	export class ApiError extends Error {
  9	    constructor(message, { status = null, payload = null, timeout = false, cancelled = false } = {}) {
 10	        super(message);
 11	        this.name = 'ApiError';
 12	        this.status = status;
 13	        this.payload = payload;
 14	        this.timeout = timeout;
 15	        this.cancelled = cancelled;
 16	    }
 17	}
 18	
 19	async function readPayload(response) {
 20	    const body = await response.text();
 21	    if (!body) {
 22	        return null;
 23	    }
 24	
 25	    if (!isJsonResponse(response.headers.get('content-type') || '')) {
 26	        return body;
 27	    }
 28	
 29	    try {
 30	        return JSON.parse(body);
 31	    } catch {
 32	        throw new ApiError('The server returned an invalid JSON response.', { status: response.status });
 33	    }
 34	}
 35	
 36	function toApiError(error, { timedOut, externalSignal }) {
 37	    if (timedOut) {
 38	        return new ApiError('The request timed out. Please try again.', { timeout: true });
 39	    }
 40	    if (externalSignal?.aborted) {
 41	        return new ApiError('The request was cancelled.', { cancelled: true });
 42	    }
 43	    if (error instanceof ApiError) {
 44	        return error;
 45	    }
 46	    return new ApiError('Unable to reach the server.');
 47	}
 48	
 49	export async function request(url, options = {}) {
 50	    const { signal: externalSignal, ...fetchOptions } = options;
 51	    const controller = new AbortController();
 52	    let timedOut = false;
 53	    const timeout = setTimeout(() => {
 54	        timedOut = true;
 55	        controller.abort();
 56	    }, REQUEST_TIMEOUT_MS);
 57	    const abortRequest = () => controller.abort();
 58	
 59	    if (externalSignal?.aborted) {
 60	        abortRequest();
 61	    } else {
 62	        externalSignal?.addEventListener('abort', abortRequest, { once: true });
 63	    }
 64	
 65	    let response;
 66	    let payload;
 67	
 68	    try {
 69	        response = await fetch(url, {
 70	            ...fetchOptions,
 71	            signal: controller.signal
 72	        });
 73	        payload = await readPayload(response);
 74	    } catch (error) {
 75	        throw toApiError(error, { timedOut, externalSignal });
 76	    } finally {
 77	        clearTimeout(timeout);
 78	        externalSignal?.removeEventListener('abort', abortRequest);
 79	    }
 80	
 81	    if (!response.ok) {
 82	        throw new ApiError(`Request failed (${response.status}).`, {
 83	            status: response.status,
 84	            payload: payload && typeof payload === 'object' ? payload : null
 85	        });
 86	    }
 87	
 88	    return payload;
 89	}
